let summary: string;
try {
  const r = run("git", ["log", "--oneline", "-1"]);
  summary = r.ok ? r.out : `bump to v${to} (git log failed: ${r.err})`;
} catch (err) {
  summary = `bump to v${to} (git log failed: ${err instanceof Error ? err.message : err})`;
}
